import { Component, Input, Output, EventEmitter, OnInit } from '@angular/core';
import { MisCompras } from 'src/app/models/mis-compras';

@Component({
  selector: 'app-hijo',
  templateUrl: './hijo.component.html',
  styleUrls: ['./hijo.component.css']
})
export class HijoComponent implements OnInit{

  @Input() compras: MisCompras[] = [];
  @Output() precioUltimaCompra = new EventEmitter <number>();


  ngOnInit(): void {
    this.precioUltimaCompra.emit(this.compras[this.compras.length -1].total);
  }

}
<li *ngFor="let compra of compras">
  {{compra.total.toFixed(2) }} euros
</li>
